Translate("deDE", "onyxias-lair", {
	title = "Onyxias Hort",
	aliases = { "Hort der Onyxia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Onyxias Hort ist eine große Höhle unter dem {link:wyrmbog}Drachensumpf{/link}, im äußersten Süden der {link:dustwallow-marsh}Marschen von Dustwallow{/link}. Ein breiter Tunnel führt vom versengten Gestein des Sumpfes hinab in die Dunkelheit, und an seinem Ende öffnet sich eine gewaltige Kammer aus schwarzem Fels, von Feuerspalten durchzogen. Dies ist der Hort von {link:onyxia}Onyxia{/link}, der Tochter von {link:deathwing}Todesschwinge{/link} und Brutmutter des schwarzen Drachenschwarms. Ihre Eier liegen in den Höhlen entlang der Wände, und ihre {link:the-night-watch}Wächter{/link} halten im Tunnel Wache. Nur wenige, die nicht zu ihrem Schwarm gehören, haben den Hort je gesehen und sind zurückgekehrt.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann {link:onyxia}Onyxia{/link} ihren Hort im Sumpf errichtete, noch wie lange die Höhle schon ihr gehörte, bevor die Sterblichen davon erfuhren. Bekannt ist, dass ihre Brut aus dem Süden heraufkam und über die {link:ogres}Oger{/link} des {red:stonemaul-ogres}Stonemaulklans{/red} herfiel. Die Oger verloren ihr Dorf und flohen nach Norden ins Schilf. {link:draz-zilb}Draz'Zilb{/link}, der Gelehrte der Stonemaul, verfolgte die Welpen mit arkanen Künsten bis zu ihrer Mutter zurück. Er glaubte nicht, dass eine Tochter Todesschwinges so weit gekommen war, nur um eine Bande von Ogern zu belagern. Warum sie gerade diesen Sumpf wählte, so nahe bei {link:theramore-isle}Theramore{/link} und den Ländern der {link:horde}Horde{/link}, hat noch niemand erfahren.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:wyrmbog}Der Drachensumpf{/link} ist zu einer Brutstätte geworden. Onyxias Eier liegen über das Drachendüster verstreut, und ihre Welpen und Drachen jagen im südlichen Sumpf. In einem nahen Hort prüft der uralte Drache {link:emberstrife}Emberstrife{/link} die Drachkin, die aufsteigen wollen, um sie zu bewachen. Nur die Stärksten des schwarzen Schwarms dürfen ihren Hort betreten. Sie müssen einen Schlüssel tragen, ein Amulett, das {red:general-drakkisath}General Drakkisath{/red} in der {red:blackrock-spire}Blackrockspitze{/red} eingestimmt hat. Ohne es versperren ihre Schutzzauber den Weg.

Manche, die keine Drachen sind, haben andere Wege zu diesem Schlüssel gefunden. Die blaue Drachin {link:haleh}Haleh{/link} aus {link:winterspring}Winterspring{/link} weiß, wie ein solches Amulett wieder ganz gemacht wird, und {link:rexxar}Rexxar{/link} weiß, wie man eines mit List und mit Blut gewinnen kann. Es heißt, dass die Brutmutter in der tiefsten Kammer ihrer Höhle ruht. Wer ihr gegenübertreten will, muss zu ihr hinabsteigen.]=],
		},
		{
			title = "Im Hort",
			text = [=[• {b}Der Tunnel.{/b} Ein langer Gang windet sich vom Sumpf hinab. Onyxianische {link:the-night-watch}Wächter{/link}, Drachkin ihrer Garde, stehen an ihm entlang und lassen keinen Fremden vorbei.
• {b}Die Nester.{/b} Tiefe Höhlen öffnen sich in den Wänden der großen Kammer, und ihre Böden sind mit Eiern bedeckt. Wenn ihre Mutter ruft, strömen die Welpen in Schwärmen aus ihnen hervor.
• {b}Die große Kammer.{/b} Eine gewaltige Halle aus schwarzem Stein am Ende des Tunnels, in der {link:onyxia}Onyxia{/link} wartet. Spalten in ihrem Boden brechen auf und speien Feuer. Wenn sie sich in die Lüfte erhebt, brennt die ganze Höhle unter ihrem Atem.]=],
		},
	},
})

